using UnityEngine; using UnityEngine.EventSystems;  /// <summary> /// 창고 드롭존 /// </summary> public class StorageDropZone : MonoBehaviour, IDropTarget, IDropHandler {     private WorldStorage storageInventory;     public bool CanAcceptDrop(DragContext context)     {         // 창고는 인벤토리에서만 받음         return context?.Item != null &&                context.SourceType == DragSourceType.Inventory;     }      public void HandleDrop(DragContext context)     {         // 창고에 아이템 추가 로직         storageInventory.AddItem(context.Item, 1);     }      public void OnDrop(PointerEventData eventData)     {         var context = ItemIconDragHandler.CurrentContext;         if (CanAcceptDrop(context))         {             HandleDrop(context);         }     } }